import { stdout } from std.io;
abstract class Shape {
    abstract area(): Int32;
    abstract name(): String;
}
class Sq implements Shape {
    s: Int32;
    construct(s: Int32) { this.s = s; }
    area(): Int32 { return this.s * this.s; }
    name(): String { return "sq"; }
}
class Rect implements Shape {
    w: Int32;
    h: Int32;
    construct(w: Int32, h: Int32) { this.w = w; this.h = h; }
    area(): Int32 { return this.w * this.h; }
    name(): String { return "rect"; }
}
class Animal { construct() { } speak(): String { return "..."; } }
class Dog extends Animal { construct() { super(); } #override speak(): String { return "woof"; } }
class Cat extends Animal { construct() { super(); } #override speak(): String { return "meow"; } }
fn main(): Void {
    mut shapes: List<Shape> = List();
    shapes.add(Sq(2));
    shapes.add(Rect(2, 5));
    for s in shapes {
        stdout.println(s.name() + "=" + s.area().to_string());
    }
    mut zoo: List<Animal> = List();
    zoo.add(Animal());
    zoo.add(Dog());
    zoo.add(Cat());
    for a in zoo { stdout.println(a.speak()); }
    mut m: Map<Int32, Animal> = Map();
    m.set(1, Dog());
    m.set(2, Cat());
    stdout.println((m.get_or_null(1) ?? Animal()).speak());
    stdout.println((m.get_or_null(9) ?? Animal()).speak());
}
